INSERT INTO prof VALUES
  (8996, $$Asia Pacific Report: Kiribati$$, 'KI', $$Coentreprise à but non lucratif$$, $$Multimedia Investments Ltd et Cafe Pacific Media, en association avec Asia Pacific Media Network$$, ARRAY['independent']::text[], NULL, $$Asia Pacific Report a été fondé en 2016 avec le contenu d'étudiants en journalisme de troisième cycle du Pacific Media Centre de l'Auckland University of Technology (AUT), avant de devenir indépendant après la fermeture du cours et du centre le 19 décembre 2020.$$, $$Le site opère désormais comme coentreprise à but non lucratif sous licence Creative Commons, dirigé par le rédacteur David Robie, sans lien direct avec l'AUT. Flux de la rubrique Kiribati du site.$$, 'high', $$Le site lui-même confirme la structure de coentreprise à but non lucratif et la rupture du lien universitaire depuis fin 2020 ; même profil que les autres flux Asia Pacific Report.$$, $$[{"url": "https://asiapacificreport.nz/about/", "note": "Coentreprise à but non lucratif entre Multimedia Investments Ltd et Cafe Pacific Media ; issu du Pacific Media Centre (AUT), indépendant depuis la fermeture du centre le 19 décembre 2020", "category": "self_described", "accessed_at": "2026-10-18"}]$$::jsonb, false),
  (8997, $$Asia Pacific Report: Marshall Islands$$, 'MH', $$Coentreprise à but non lucratif$$, $$Multimedia Investments Ltd et Cafe Pacific Media, en association avec Asia Pacific Media Network$$, ARRAY['independent']::text[], NULL, $$Asia Pacific Report a été fondé en 2016 avec le contenu d'étudiants en journalisme de troisième cycle du Pacific Media Centre de l'Auckland University of Technology (AUT), avant de devenir indépendant après la fermeture du cours et du centre le 19 décembre 2020.$$, $$Le site opère désormais comme coentreprise à but non lucratif sous licence Creative Commons, dirigé par le rédacteur David Robie, sans lien direct avec l'AUT. Flux de la rubrique Îles Marshall du site.$$, 'high', $$Le site lui-même confirme la structure de coentreprise à but non lucratif et la rupture du lien universitaire depuis fin 2020 ; même profil que les autres flux Asia Pacific Report.$$, $$[{"url": "https://asiapacificreport.nz/about/", "note": "Coentreprise à but non lucratif entre Multimedia Investments Ltd et Cafe Pacific Media ; issu du Pacific Media Centre (AUT), indépendant depuis la fermeture du centre le 19 décembre 2020", "category": "self_described", "accessed_at": "2026-10-18"}]$$::jsonb, false),
  (8998, $$Asia Pacific Report: Nauru$$, 'NR', $$Coentreprise à but non lucratif$$, $$Multimedia Investments Ltd et Cafe Pacific Media, en association avec Asia Pacific Media Network$$, ARRAY['independent']::text[], NULL, $$Asia Pacific Report a été fondé en 2016 avec le contenu d'étudiants en journalisme de troisième cycle du Pacific Media Centre de l'Auckland University of Technology (AUT), avant de devenir indépendant après la fermeture du cours et du centre le 19 décembre 2020.$$, $$Le site opère désormais comme coentreprise à but non lucratif sous licence Creative Commons, dirigé par le rédacteur David Robie, sans lien direct avec l'AUT. Flux de la rubrique Nauru du site.$$, 'high', $$Le site lui-même confirme la structure de coentreprise à but non lucratif et la rupture du lien universitaire depuis fin 2020 ; même profil que les autres flux Asia Pacific Report.$$, $$[{"url": "https://asiapacificreport.nz/about/", "note": "Coentreprise à but non lucratif entre Multimedia Investments Ltd et Cafe Pacific Media ; issu du Pacific Media Centre (AUT), indépendant depuis la fermeture du centre le 19 décembre 2020", "category": "self_described", "accessed_at": "2026-10-18"}]$$::jsonb, false),
  (9000, $$Asia Pacific Report: Solomon Islands$$, 'SB', $$Coentreprise à but non lucratif$$, $$Multimedia Investments Ltd et Cafe Pacific Media, en association avec Asia Pacific Media Network$$, ARRAY['independent']::text[], NULL, $$Asia Pacific Report a été fondé en 2016 avec le contenu d'étudiants en journalisme de troisième cycle du Pacific Media Centre de l'Auckland University of Technology (AUT), avant de devenir indépendant après la fermeture du cours et du centre le 19 décembre 2020.$$, $$Le site opère désormais comme coentreprise à but non lucratif sous licence Creative Commons, dirigé par le rédacteur David Robie, sans lien direct avec l'AUT. Flux de la rubrique Îles Salomon du site.$$, 'high', $$Le site lui-même confirme la structure de coentreprise à but non lucratif et la rupture du lien universitaire depuis fin 2020 ; même profil que les autres flux Asia Pacific Report.$$, $$[{"url": "https://asiapacificreport.nz/about/", "note": "Coentreprise à but non lucratif entre Multimedia Investments Ltd et Cafe Pacific Media ; issu du Pacific Media Centre (AUT), indépendant depuis la fermeture du centre le 19 décembre 2020", "category": "self_described", "accessed_at": "2026-10-18"}]$$::jsonb, false),
  (9001, $$Asia Pacific Report: Tuvalu$$, 'TV', $$Coentreprise à but non lucratif$$, $$Multimedia Investments Ltd et Cafe Pacific Media, en association avec Asia Pacific Media Network$$, ARRAY['independent']::text[], NULL, $$Asia Pacific Report a été fondé en 2016 avec le contenu d'étudiants en journalisme de troisième cycle du Pacific Media Centre de l'Auckland University of Technology (AUT), avant de devenir indépendant après la fermeture du cours et du centre le 19 décembre 2020.$$, $$Le site opère désormais comme coentreprise à but non lucratif sous licence Creative Commons, dirigé par le rédacteur David Robie, sans lien direct avec l'AUT. Flux de la rubrique Tuvalu du site.$$, 'high', $$Le site lui-même confirme la structure de coentreprise à but non lucratif et la rupture du lien universitaire depuis fin 2020 ; même profil que les autres flux Asia Pacific Report.$$, $$[{"url": "https://asiapacificreport.nz/about/", "note": "Coentreprise à but non lucratif entre Multimedia Investments Ltd et Cafe Pacific Media ; issu du Pacific Media Centre (AUT), indépendant depuis la fermeture du centre le 19 décembre 2020", "category": "self_described", "accessed_at": "2026-10-18"}]$$::jsonb, false),
  (8999, $$Island Times$$, 'PW', $$Entreprise de presse privée (structure du capital non publiée)$$, $$Leilani Reklai (éditrice et rédactrice en chef)$$, ARRAY['commercial_generalist']::text[], NULL, $$Journal privé de Koror présenté par la PINA comme le principal journal des Palaos : deux éditions par semaine, plus de 800 exemplaires, diffusé surtout à Koror et Airai, avec un site web.$$, $$Son éditrice, Leilani Reklai, est aussi femme politique (gouverneure de l'État d'Aimeliik depuis 2007) ; aucune ligne partisane du journal n'est documentée dans les sources consultées. En octobre 2024, le journal et son éditrice ont été poursuivis en diffamation par la société Surangel and Sons au sujet d'un article du 29 octobre ; le Palau Media Council a dénoncé une atteinte à la liberté de la presse.$$, 'low', $$Éditrice, périodicité et diffusion documentées par la PINA et Wikipédia ; propriété et financement non publiés. Le mandat politique de l'éditrice justifie une revue.$$, $$[{"url": "https://pina.com.fj/pina-members/island-times/", "note": "Fiche membre PINA : éditrice Leilani Reklai, deux éditions par semaine, plus de 800 exemplaires", "category": "media_research", "accessed_at": "2026-10-18"}, {"url": "https://en.wikipedia.org/wiki/Leilani_Reklai", "note": "Rédactrice en chef de l'Island Times, gouverneure d'Aimeliik depuis 2007 ; plainte en diffamation de Surangel and Sons (octobre 2024)", "category": "reference", "accessed_at": "2026-10-18"}, {"url": "https://www.mvariety.com/news/regional_world/palau-media-council-lawsuit-against-island-times-an-assault-on-press-freedom/article_7dda9d8a-99ef-11ef-866e-eb917757b3e7.html/", "note": "Le Palau Media Council qualifie la plainte contre Island Times d’atteinte à la liberté de la presse (titre de l’article)", "category": "press_freedom", "accessed_at": "2026-10-18"}]$$::jsonb, true);
DO $$
DECLARE bad int; n int;
BEGIN
  -- Each target must be the publisher of that name in that country, and must not have a profile yet.
  SELECT count(*) INTO bad FROM prof x
   WHERE NOT EXISTS (SELECT 1 FROM publishers p JOIN countries c ON c.id = p.country_id
                      WHERE p.id = x.publisher_id AND p.name = x.name AND c.iso_code = x.iso)
      OR EXISTS (SELECT 1 FROM editorial_profiles e WHERE e.publisher_id = x.publisher_id);
  IF bad > 0 THEN RAISE EXCEPTION '% of 6 publishers are not the expected outlet or already have a profile - nothing changed', bad; END IF;
  INSERT INTO editorial_profiles (publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, classification_date, last_reviewed, evidence_date, review_required)
  SELECT publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, DATE '2026-10-18', DATE '2026-10-18', DATE '2026-10-18', review_required FROM prof;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 6 THEN RAISE EXCEPTION 'inserted %, expected 6', n; END IF;
END $$;
SELECT 'profile|' || p.id || '|' || p.name || '|' || array_to_string(e.classification_tags, ',') || '|' || e.confidence || '|review ' || e.review_required
       || '|' || jsonb_array_length(e.evidence_sources) || ' sources'
  FROM editorial_profiles e JOIN publishers p ON p.id = e.publisher_id WHERE e.publisher_id IN (8996, 8997, 8998, 9000, 9001, 8999) ORDER BY p.id;
SELECT 'gap|' || count(*) || ' active publishers without a profile'
  FROM publishers p LEFT JOIN editorial_profiles e ON e.publisher_id = p.id WHERE p.feed_status = 'active' AND e.id IS NULL;
COMMIT;
